<script setup lang="ts">import {onMounted,ref} from 'vue';import {supabase} from '@/lib/supabase';import {useRouter} from 'vue-router';const rows=ref<any[]>([]),error=ref(''),q=ref(''),router=useRouter();onMounted(async()=>{const {data,error:e}=await supabase.from('sales').select('id,receipt_no,customer_id,grand_total,payment_method,created_at').order('created_at',{ascending:false}).limit(250);if(e)error.value=e.message;else rows.value=data??[]})</script><template><section class="page-wrap"><div class="page-heading"><div><h1>Receipts</h1><p>Open, print or save completed sales receipts.</p></div></div><input v-model="q" class="control search" placeholder="Search receipt number or customer ID"><p v-if="error" class="alert">{{error}}</p><div class="table-scroll mt"><table><thead><tr><th>Receipt</th><th>Customer ID</th><th>Total</th><th>Payment</th><th>Date</th><th></th></tr></thead><tbody><tr v-for="r in rows.filter(x=>String(x.receipt_no??x.id).toLowerCase().includes(q.toLowerCase())||String(x.customer_id??'').includes(q))" :key="r.id"><td>{{r.receipt_no??r.id}}</td><td>{{r.customer_id??'Walk-in'}}</td><td>UGX {{Number(r.grand_total).toLocaleString()}}</td><td>{{r.payment_method}}</td><td>{{new Date(r.created_at).toLocaleString()}}</td><td><button class="link" @click="router.push(`/receipts/${r.id}`)">View receipt</button></td></tr></tbody></table></div></section></template>